#define HMF_NPICK ((int)(sizeof hmf_picks / sizeof hmf_picks[0]))

static int hmf_choose(size_t n, float snr, float fd, size_t *band, int *u, int *k)
{
  const hmf_pick *best = 0; float bd = 1e30f;
  for (int i = 0; i < HMF_NPICK; i++) {
    if (hmf_picks[i].n != (unsigned)n) continue;
    /* nearest design point; snr is weighted because the gate moves with it far
       faster than it moves with fd */
    float ds = hmf_picks[i].snr - snr;
    float rf = hmf_picks[i].fd > fd ? hmf_picks[i].fd / fd : fd / hmf_picks[i].fd;
    float d = 4.0f * ds * ds + (rf - 1.0f);
    if (d < bd) { bd = d; best = &hmf_picks[i]; }
  }
  if (!best) return 0;
  if (band) *band = best->band;
  if (u) *u = best->u;
  if (k) *k = best->k;
  return 1;
}

/* raw=0 gives the interpolated recovery (calibrates the gate); raw=1 gives the
   raw-sample recovery (bounds the cheap pre-scan).  They differ by ~6% at U=2
   and ~18% at U=1, and confusing them costs detections. */
/* raw=0: interpolated recovery, which calibrates the gate.
   raw=1: raw-sample recovery of the full coarse grid, which bounds the pre-scan.
   raw=2: raw recovery of the EVEN half alone, which bounds the early-out that
          skips the odd transform.  All three differ, and swapping any pair of
          them costs detections rather than time. */
static float hmf_recovery(size_t n, size_t band, int u, int k, int raw)
{
  for (int i = 0; i < HMF_NPICK; i++)
    if (hmf_picks[i].n == (unsigned)n && hmf_picks[i].band == (unsigned)band
        && hmf_picks[i].u == u && hmf_picks[i].k == k)
      return raw == 2 ? hmf_picks[i].graw1
           : raw == 1 ? hmf_picks[i].graw : hmf_picks[i].g;
  /* Unknown combination (a pinned band, say).  For the interpolated figure
     assume no loss; for the raw figure assume the worst plausible loss.  Both
     choices err toward triggering more often, which costs time but cannot cost
     a detection. */
  return raw ? 0.70f : 1.0f;   /* conservative: widens the gates, never narrows */
}

static float hmf_threshold(float f_eff, float snr, float fd)
{
  int ai = 0; float bd = 1e30f;
  for (int i = 0; i < HMF_NFD; i++) {
    float d = fd > hmf_fd_grid[i] ? fd / hmf_fd_grid[i] : hmf_fd_grid[i] / fd;
    if (d < bd) { bd = d; ai = i; }
  }
  /* Clamp rather than extrapolate.  Outside the grid the model is untested, and
     a clamped threshold errs toward triggering more often, which costs time but
     cannot cost a detection. */
  if (f_eff <= hmf_f_grid[0]) f_eff = hmf_f_grid[0];
  if (f_eff >= hmf_f_grid[HMF_NF-1]) f_eff = hmf_f_grid[HMF_NF-1];
  if (snr <= hmf_snr_grid[0]) snr = hmf_snr_grid[0];
  if (snr >= hmf_snr_grid[HMF_NSNR-1]) snr = hmf_snr_grid[HMF_NSNR-1];
  int fi = 0; while (fi < HMF_NF-2 && hmf_f_grid[fi+1] < f_eff) fi++;
  int si = 0; while (si < HMF_NSNR-2 && hmf_snr_grid[si+1] < snr) si++;
  float tf = (f_eff - hmf_f_grid[fi]) / (hmf_f_grid[fi+1] - hmf_f_grid[fi]);
  float ts = (snr - hmf_snr_grid[si]) / (hmf_snr_grid[si+1] - hmf_snr_grid[si]);
  float a = hmf_tc[ai][si][fi]   + tf * (hmf_tc[ai][si][fi+1]   - hmf_tc[ai][si][fi]);
  float b = hmf_tc[ai][si+1][fi] + tf * (hmf_tc[ai][si+1][fi+1] - hmf_tc[ai][si+1][fi]);
  return a + ts * (b - a);
}
#endif

